query:
PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?agency ?statusLabel ?launchDate
WHERE {
  ?mission a ?type ;
           ss:name ?name ;
           ss:agency ?agency ;
           ss:status ?status ;
           ss:launch-date ?launchDate .
  ?type rdfs:subClassOf ss:Mission .
  ?status rdfs:label ?statusLabel .
}
ORDER BY ?launchDate

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name ?typeLabel ?distanceAU ?radiusKm
WHERE {
  ?body a ?type ;
        ss:name ?name ;
        ss:avg-distance-from-sun-au ?distanceAU ;
        ss:radius-km ?radiusKm .
  ?type rdfs:subClassOf ss:CelestialBody ;
        rdfs:label ?typeLabel .
}
ORDER BY ?distanceAU

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?date ?eventType ?description ?nearestBody ?distanceKm ?velocityKmS
WHERE {
  ?mission ss:name "Voyager 1" ;
           ss:has-event ?event .
  ?event a ?type ;
         ss:date ?date ;
         ss:description ?description ;
         ss:distance-from-body-km ?distanceKm ;
         ss:velocity-km-s ?velocityKmS .
  ?type rdfs:label ?eventType .
  OPTIONAL {
    ?event ss:nearest-body ?body .
    ?body ss:name ?nearestBody .
  }
}
ORDER BY ?date

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>

SELECT ?missionName ?date ?description ?bodyName ?distanceKm
WHERE {
  ?mission ss:name ?missionName ;
           ss:has-event ?event .
  ?event a ss:FlybyEvent ;
         ss:date ?date ;
         ss:description ?description ;
         ss:distance-from-body-km ?distanceKm ;
         ss:nearest-body ?body .
  ?body ss:name ?bodyName .
}
ORDER BY ?date

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>

SELECT ?missionName ?agency ?launchDate
WHERE {
  ?body ss:name "Mars" .
  ?mission ss:target-body ?body ;
           ss:name ?missionName ;
           ss:agency ?agency ;
           ss:launch-date ?launchDate .
}
ORDER BY ?launchDate

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?agency (COUNT(?mission) AS ?count)
WHERE {
  ?mission a ?type ;
           ss:agency ?agency .
  ?type rdfs:subClassOf ss:Mission .
}
GROUP BY ?agency
ORDER BY DESC(?count)

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?date ?missionName ?eventType ?description ?distanceAU
WHERE {
  ?mission ss:name ?missionName ;
           ss:has-event ?event .
  ?event a ?type ;
         ss:date ?date ;
         ss:description ?description ;
         ss:position ?pos .
  ?type rdfs:label ?eventType .
  ?pos ss:distance-au ?distanceAU .
}
ORDER BY ?date

PREFIX ss: <http://trustgraph.ai/ontology/solar-system#>

SELECT ?missionName ?date ?description ?distanceAU
WHERE {
  ?mission ss:name ?missionName ;
           ss:has-event ?event .
  ?event ss:date ?date ;
         ss:description ?description ;
         ss:position ?pos .
  ?pos ss:distance-au ?distanceAU .
}
ORDER BY DESC(?distanceAU)
